    buildQr();
  }, [key]);

  if (!h.documentNumber) {
    return <div className="empty">No opening stock data available.</div>;
  }

  const totalQty = items.reduce((s, r) => s + Number(r.quantity || 0), 0);
  const totalValue = items.reduce((s, r) => s + Number(r.lineTotal || 0), 0);

  return (
    <div className="page">
      <button className="print-button" onClick={() => window.print()}>
        Print opening stock
      </button>

      <div className="document">
        <div className="top-line" />

        <div className="header">
          <div className="brand">
            {(h.companyLogoPath || h.company_logo_path) ? (
              <img className="logo" src={h.companyLogoPath || h.company_logo_path} />
            ) : (
              <div className="logo-fallback">{initials(h.companyName)}</div>
            )}

            <div>
              <div className="company-name">{h.companyName || "Company"}</div>
              <div className="company-meta">
                <div>{[h.companyAddress, h.companyPostalCode, h.companyCity].filter(Boolean).join(", ")}</div>
                <div>Tax No: {h.companyTaxNumber || "-"}</div>
                <div>Reg No: {h.companyRegistrationNumber || "-"}</div>
                <div>{[h.companyEmail, h.companyPhone].filter(Boolean).join(" | ")}</div>
              </div>
            </div>
          </div>

          <div className="doc-title">
            <div className="badge">Initial Inventory</div>
            <h1>OPENING STOCK</h1>
            <div className="doc-no">{h.documentNumber}</div>
            <div className="status">{h.status || "DRAFT"}</div>
          </div>
        </div>

        <div className="info-strip">
          <div className="info-box">
            <span className="label">Document Date</span>
            <span className="value">{formatDate(h.documentDate)}</span>
          </div>
          <div className="info-box">
            <span className="label">Warehouse</span>
            <span className="value">{[h.warehouseCode, h.warehouseName].filter(Boolean).join(" - ")}</span>
          </div>
          <div className="info-box">
            <span className="label">Created By</span>
            <span className="value">{h.createdBy || model.username || "-"}</span>
          </div>
          <div className="info-box">
            <span className="label">Lines</span>
            <span className="value">{items.length}</span>
          </div>
        </div>

        <div className="items-wrap">
          <div className="items-head">
            <h2>Opening Stock Items</h2>
            <span>{items.length} line{items.length === 1 ? "" : "s"}</span>
          </div>

          <table>
            <thead>
              <tr>
                <th>#</th>
                <th>Product</th>
                <th>Barcode</th>
                <th>Batch</th>
                <th>Serial</th>
                <th>Expiry</th>
                <th className="right">Qty</th>
                <th>Unit</th>
                <th className="right">Unit Cost</th>
                <th className="right">Total</th>
              </tr>
            </thead>
            <tbody>
              {items.map((row, index) => (
                <tr key={index}>
                  <td>{row.lineNo || index + 1}</td>
                  <td>
                    <div className="product-code">{row.productCode || ""}</div>
                    <div className="product-name">{row.productName || ""}</div>
                  </td>
                  <td>{row.barcode || ""}</td>
                  <td>{row.batchNumber || ""}</td>
                  <td>{row.serialNumber || ""}</td>
                  <td>{formatDate(row.expiryDate)}</td>
                  <td className="right">{qty(row.quantity)}</td>
                  <td>{row.unitCode || ""}</td>
                  <td className="right">{money(row.unitCost)}</td>
                  <td className="right">{money(row.lineTotal)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        <div className="bottom-grid">
          <div>
            {h.note && (
              <div className="note-box">
                <span className="label">Note</span>
                {h.note}
              </div>
            )}

            <div className="qr-area">
              <div className="qr-box">
                {qr && <img src={qr} />}
                <div>Opening stock reference</div>
              </div>
            </div>
          </div>

          <div className="summary-box">
            <div className="summary-row">
              <span>Total Quantity</span>
              <b>{qty(totalQty)}</b>
            </div>
            <div className="summary-row total">
              <span>Total Value</span>
              <b>{money(totalValue)}</b>
            </div>
          </div>
        </div>

        <div className="signatures">
          <div className="signature">Prepared by</div>
          <div className="signature">Approved by</div>
        </div>

        <div className="footer">
          This opening stock document was generated by Axon ERP.
        </div>
      </div>
    </div>
  );
}

function render() {
  ReactDOM.render(<App />, document.getElementById("root"));
}

appsmith.onReady(() => {
  render();
  appsmith.onModelChange(render);
});
